-- The door-step handover code is removed.
--
-- A delivery could be blocked until the customer read out a four-digit code,
-- but nothing ever gave the customer the code: it was generated by a
-- dispatch-only button and returned once, to dispatch. The only thing the
-- feature could do in practice was keep a driver standing outside an order
-- that was already paid for, and add a step for the dispatcher.
--
-- The column held hashes of codes that no longer exist, so there is nothing
-- here worth keeping.
ALTER TABLE "Delivery" DROP COLUMN IF EXISTS "otpHash";

-- The setting that switched it on, global and per-branch alike. Left behind it
-- would be a stored value no code reads, which is how a removed feature comes
-- back.
DELETE FROM "Setting" WHERE "key" = 'delivery.require_handover_code';
